 switch($action){
 case 'profile': $name=trim($_POST['name']??''); if(!$name || strlen($name)>100) throw new RuntimeException('Enter a valid name.'); q('UPDATE users SET name=?,phone=? WHERE id=?',[$name,substr(trim($_POST['phone']??''),0,30),$u['id']]); if(!empty($_POST['password'])) { if(!password_verify($_POST['current_password']??'',$u['password']) || strlen($_POST['password'])<10) throw new RuntimeException('Verify your current password and use at least 10 characters.'); q('UPDATE users SET password=? WHERE id=?',[password_hash($_POST['password'],PASSWORD_DEFAULT),$u['id']]); } break;
 case 'read': q('UPDATE notifications SET read_at=NOW() WHERE user_id=?',[$u['id']]); break;
 case 'address': $address=trim($_POST['address']??''); if(!$address || !one('SELECT id FROM delivery_areas WHERE barangay=? AND active=1',[$_POST['barangay']??''])) throw new RuntimeException('Enter an address in an available area.'); $lat=$_POST['latitude']??''; $lng=$_POST['longitude']??''; if(($lat!=='' && (!is_numeric($lat)||abs((float)$lat)>90)) || ($lng!=='' && (!is_numeric($lng)||abs((float)$lng)>180))) throw new RuntimeException('Invalid coordinates.'); if($id){if(!one('SELECT id FROM addresses WHERE id=? AND customer_id=?',[$id,$u['id']]))throw new RuntimeException('Address not found.');q('UPDATE addresses SET address=?,barangay=?,latitude=?,longitude=? WHERE id=? AND customer_id=?',[$address,$_POST['barangay'],$lat===''?null:$lat,$lng===''?null:$lng,$id,$u['id']]);}else q('INSERT INTO addresses(customer_id,address,barangay,latitude,longitude) VALUES(?,?,?,?,?)',[$u['id'],$address,$_POST['barangay'],$lat===''?null:$lat,$lng===''?null:$lng]); break;
