 case 'subscription': $days=array_values(array_unique(array_map('intval',$_POST['days']??[]))); if(!$days || array_diff($days,range(1,7))) throw new RuntimeException('Select valid weekdays.'); $start=$_POST['start_date']??''; if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start) || date('Y-m-d',strtotime($start))!==$start || $start<date('Y-m-d')) throw new RuntimeException('Choose a valid start date.'); $time=$_POST['preferred_time']??''; if(!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/',$time)) throw new RuntimeException('Invalid delivery time.'); $qty=(int)$_POST['quantity']; if($qty<1||$qty>100 || !one('SELECT id FROM products WHERE id=? AND active=1',[(int)$_POST['product_id']]) || !one('SELECT id FROM addresses WHERE id=? AND customer_id=?',[(int)$_POST['address_id'],$u['id']]) || !in_array($_POST['payment_method'],['COD','GCash','Maya'],true)) throw new RuntimeException('Invalid subscription details.'); q('INSERT INTO subscriptions(customer_id,product_id,address_id,quantity,selected_days,preferred_time,payment_method,start_date,next_delivery_date) VALUES(?,?,?,?,?,?,?,?,?)',[$u['id'],$_POST['product_id'],$_POST['address_id'],$qty,implode(',',$days),$time,$_POST['payment_method'],$start,next_date($days,$start,true)]); break;
 case 'subscription_status': $s=one('SELECT * FROM subscriptions WHERE id=? AND customer_id=? FOR UPDATE',[$id,$u['id']]); $state=$_POST['status']; if(!$s || $s['status']==='Cancelled' || !in_array($state,['Active','Paused','Cancelled'],true)) throw new RuntimeException('Invalid subscription change.'); $next=next_date(array_map('intval',explode(',',$s['selected_days'])),max(date('Y-m-d'),$s['start_date']),true); q('UPDATE subscriptions SET status=?,next_delivery_date=? WHERE id=?',[$state,$next,$id]); break;
 case 'reference': $o=one('SELECT * FROM orders WHERE id=? AND customer_id=?',[$id,$u['id']]); $ref=trim($_POST['reference']??''); if(!$o || $o['payment_method']==='COD' || !$ref || strlen($ref)>100) throw new RuntimeException('Invalid payment reference.'); q("UPDATE payments SET payment_reference=? WHERE order_id=? AND payment_status IN ('Pending','Failed')",[$ref,$id]); break;
