 case 'cancel': $o=one('SELECT * FROM orders WHERE id=? AND customer_id=? FOR UPDATE',[$id,$u['id']]); if(!$o || $o['status']!=='Pending') throw new RuntimeException('Only pending orders can be cancelled.'); q("UPDATE orders SET status='Cancelled' WHERE id=?",[$id]); q('INSERT INTO order_status_history(order_id,actor_id,status) VALUES(?,?,?)',[$id,$u['id'],'Cancelled']); notify((int)$u['id'],'Your order was cancelled.'); break;
 case 'assign': $o=one('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id]); $r=one("SELECT * FROM riders WHERE user_id=? AND availability<>'Offline'",[(int)$_POST['rider_id']]); if(!$o || !$r || !in_array($o['status'],['Confirmed','Preparing','Assigned'],true)) throw new RuntimeException('Confirm the order and select an available rider.'); q("UPDATE orders SET rider_id=?,status='Assigned' WHERE id=?",[$r['user_id'],$id]); q('INSERT INTO order_status_history(order_id,actor_id,status) VALUES(?,?,?)',[$id,$u['id'],'Assigned']); notify((int)$o['customer_id'],'A rider has been assigned to '.$o['order_number']); break;
 case 'status': $o=one('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id]); if(!$o || ($role==='rider' && (int)$o['rider_id']!==(int)$u['id'])) throw new RuntimeException('Delivery not assigned to you.'); $state=$_POST['status']; if($state==='Picked Up'){ if($role!=='rider' || $o['status']!=='Assigned') throw new RuntimeException('Pickup is available for assigned orders.'); q('UPDATE orders SET picked_up_at=NOW() WHERE id=?',[$id]); q('INSERT INTO order_status_history(order_id,actor_id,status,note) VALUES(?,?,?,?)',[$id,$u['id'],'Assigned','Picked up from station']); break; } $trans=['Pending'=>['Confirmed','Cancelled'],'Confirmed'=>['Preparing','Cancelled'],'Preparing'=>['Cancelled'],'Assigned'=>['Out for Delivery','Cancelled'],'Out for Delivery'=>['Delivered']]; if(!in_array($state,$trans[$o['status']]??[],true) || ($role==='rider' && !in_array($state,['Out for Delivery','Delivered'],true))) throw new RuntimeException('Invalid status transition.'); if($state==='Out for Delivery' && !$o['picked_up_at']) throw new RuntimeException('Mark the order picked up first.'); q('UPDATE orders SET status=?,delivered_at=IF(?=?,NOW(),delivered_at) WHERE id=?',[$state,$state,'Delivered',$id]); if($state==='Delivered' && $o['payment_method']==='COD') q("UPDATE payments SET payment_status='Paid',paid_at=NOW() WHERE order_id=?",[$id]); q('INSERT INTO order_status_history(order_id,actor_id,status) VALUES(?,?,?)',[$id,$u['id'],$state]); notify((int)$o['customer_id'],"Your order {$o['order_number']} is now $state."); break;
 case 'schedule': $o=one('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id]);$date=str_replace('T',' ',$_POST['scheduled_at']??'');$parsed=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$date);if(!$o || !in_array($o['status'],['Pending','Confirmed','Preparing','Assigned'],true)||!$parsed||$parsed->format('Y-m-d H:i')!==$date||$parsed->getTimestamp()<time())throw new RuntimeException('Choose a future time for an order awaiting delivery.');q('UPDATE orders SET scheduled_at=? WHERE id=?',[$date,$id]);q('INSERT INTO order_status_history(order_id,actor_id,status,note) VALUES(?,?,?,?)',[$id,$u['id'],$o['status'],'Rescheduled to '.$date]);notify((int)$o['customer_id'],'Your delivery '.$o['order_number'].' has been rescheduled to '.$date.'.');break;
 case 'payment': $state=$_POST['payment_status']; if(!in_array($state,['Pending','Paid','Failed','Refunded'],true)) throw new RuntimeException('Invalid payment status.'); q('UPDATE payments SET payment_status=?,paid_at=IF(?=?,NOW(),NULL) WHERE order_id=?',[$state,$state,'Paid',$id]); break;
 case 'product': $name=trim($_POST['name']??''); $price=filter_var($_POST['price']??'',FILTER_VALIDATE_FLOAT); if(!$name || $price===false || $price<=0) throw new RuntimeException('Enter a product name and positive price.'); if($id) q('UPDATE products SET name=?,description=?,price=?,active=? WHERE id=?',[$name,$_POST['description']??'',$price,isset($_POST['active'])?1:0,$id]); else q('INSERT INTO products(station_id,name,description,price) VALUES(1,?,?,?)',[$name,$_POST['description']??'',$price]); break;
 case 'area': $name=trim($_POST['barangay']??''); $fee=filter_var($_POST['fee']??'',FILTER_VALIDATE_FLOAT); if(!$name || $fee===false || $fee<0) throw new RuntimeException('Enter a barangay and nonnegative fee.'); if($id) q('UPDATE delivery_areas SET barangay=?,fee=?,active=? WHERE id=?',[$name,$fee,isset($_POST['active'])?1:0,$id]); else q('INSERT INTO delivery_areas(station_id,barangay,fee) VALUES(1,?,?)',[$name,$fee]); break;
 case 'station': if(!trim($_POST['name']??'')) throw new RuntimeException('Station name is required.'); q('UPDATE water_stations SET name=?,address=?,phone=?,payment_instructions=? WHERE id=1',[$_POST['name'],$_POST['address'],$_POST['phone'],$_POST['payment_instructions']]); break;
 case 'rider': if(!filter_var($_POST['email'],FILTER_VALIDATE_EMAIL)||strlen($_POST['password'])<10||!trim($_POST['name'])) throw new RuntimeException('Provide a name, valid email and password of at least 10 characters.'); q("INSERT INTO users(name,email,password,role,phone) VALUES(?,?,?,'rider',?)",[$_POST['name'],$_POST['email'],password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['phone']]); q('INSERT INTO riders(user_id,station_id) VALUES(?,1)',[$db->lastInsertId()]); break;
 case 'availability': if(!in_array($_POST['availability'],['Available','Busy','Offline'],true)) throw new RuntimeException('Invalid availability.'); q('UPDATE riders SET availability=? WHERE user_id=?',[$_POST['availability'],$u['id']]); break;
 case 'location': if(!one("SELECT id FROM orders WHERE rider_id=? AND status IN ('Assigned','Out for Delivery')",[$u['id']])) throw new RuntimeException('An active delivery is required to share location.'); if(!is_numeric($_POST['latitude']??null)||!is_numeric($_POST['longitude']??null)||abs((float)$_POST['latitude'])>90||abs((float)$_POST['longitude'])>180) throw new RuntimeException('Invalid location.'); q('INSERT INTO rider_locations(rider_id,latitude,longitude) VALUES(?,?,?) ON DUPLICATE KEY UPDATE latitude=VALUES(latitude),longitude=VALUES(longitude),updated_at=NOW()',[$u['id'],$_POST['latitude'],$_POST['longitude']]); break;
 }
 $db->commit();
 } catch(Throwable $ex){ $db->rollBack(); throw $ex; }
}
